window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-729fbdfbafa9bce4"]={"versions": [{"id": "FIG-729fbdfbafa9bce4", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm (<code>cmp ArchitectureView-DeterministicClient</code>) zur Darstellung der Schnittstellenarchitektur auf System- und Prozessebene.</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die Interaktion zwischen einer deterministischen Adaptive Application und dem funktionalen Cluster <em>Execution Management</em> (<code>ara::exec</code>) der AUTOSAR Adaptive Platform (Release R18-03 / R1.4.0).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Abstraktion des Prozesslebenszyklus sowie die Entkopplung von nicht-deterministischen Plattform- und OS-Ressourcen (Systemuhr, Host-Threading, OS-Zufallsgeneratoren), um reproduzierbare Berechnungen (z. B. für automatisierte Fahrfunktionen, Replay-Simulationen und SIL/HIL-Validierung) zu garantieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Komponenten (UML Components)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Application</code>:</strong> POSIX-basierter Prozess der Adaptive Application, welcher Algorithmen mit deterministischer Ausführungscharakteristik kapselt. Fungiert als Client gegenüber beiden Schnittstellen.</li>\n<li><strong><code>Execution Management</code>:</strong> Zentraler Plattform-Daemon der Adaptive Platform (<code>ara::exec</code>), zuständig für Prozessüberwachung, deterministisches Scheduling und Lifecycle-Management. Stellt die korrespondierenden Ports bereit.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Klassen (Namespace <code>«ara::exec»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>DeterministicClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Zugriffspunkt für deterministische Ausführungsmodelle.</li>\n<li>Methoden:</li>\n<li><code>+ GetActivationTime()</code>: Liefert den deterministischen Zeitstempel des aktuellen Ausführungszyklus (unabhängig von der realen Host-Laufzeit).</li>\n<li><code>+ GetNextActivationTime()</code>: Liefert den geplanten deterministischen Startzeitpunkt des Folgezyklus.</li>\n<li><code>+ GetRandom()</code>: Liefert pseudo-zufällige Werte aus einem reproduzierbaren, durch das Execution Management synchronisierten PRNG-Zustand.</li>\n<li><code>+ RunWorkerPool()</code>: Triggert die parallele Abarbeitung deterministischer Teilaufgaben über einen verwalteten Worker-Pool unter Vermeidung von Race Conditions.</li>\n<li><code>+ WaitForNextActivation()</code>: Blockierender Synchronisationspunkt, der den Prozess bis zur nächsten deterministischen Zyklus-Freigabe suspendiert.</li>\n<li><strong><code>ApplicationClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Standard-Schnittstelle zur Lebenszyklus-Rückmeldung an das Execution Management.</li>\n<li>Methoden:</li>\n<li><code>+ ReportApplicationState()</code>: Meldet interne Prozesszustände (z. B. <code>kRunning</code>, <code>kTerminating</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Pfade</p>\n<ul class=\"fig-list\">\n<li><strong>Provided / Required Ports:</strong></li>\n<li><code>Application</code> nutzt (Required Interface / Socket) die Schnittstellen <code>DeterministicClient</code> und <code>ApplicationClient</code>.</li>\n<li><code>Execution Management</code> implementiert und exponiert (Provided Interface / Ball) beide Ports via IPC.</li>\n<li><strong>Kontrollpfad <code>Start / Terminate</code>:</strong></li>\n<li>Gerichtete Kontrollbeziehung (gestrichelte Linie) vom <code>Execution Management</code> zur <code>Application</code>. Signalisiert die Erzeugung (POSIX <code>fork</code>/<code>exec</code>) und Terminierung (<code>SIGTERM</code>/<code>SIGKILL</code>) des Prozesses.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Prozessinitialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> startet die <code>Application</code> (<code>Start</code>).</li>\n<li>Die Applikation initialisiert ihre Ressourcen und meldet über <code>ApplicationClient::ReportApplicationState(kRunning)</code> ihre Betriebsbereitschaft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deterministische Regelschleife (Zyklische Abarbeitung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Applikation ruft blockierend <code>DeterministicClient::WaitForNextActivation()</code> auf.</li>\n<li>Nach Trigger durch das <code>Execution Management</code> erwacht die Applikation im definierten Zyklus.</li>\n<li>Abfrage der logischen Zykluszeit über <code>GetActivationTime()</code> und optional <code>GetNextActivationTime()</code>.</li>\n<li>Bei Randomisierung Nutzung von <code>GetRandom()</code>; bei Datenparallelismus Ausführung über <code>RunWorkerPool()</code>.</li>\n<li>Abschluss der Zyklusberechnung; Rücksprung zu <code>WaitForNextActivation()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prozessterminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> initiiert den Shutdown (<code>Terminate</code>).</li>\n<li>Die Applikation verlässt die Regelschleife, meldet <code>ReportApplicationState(kTerminating)</code> und gibt Ressourcen frei.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Verbot direkter POSIX-Aufrufe:</strong> Entwickler deterministischer Applikationen dürfen keine nicht-deterministischen OS-Primitives verwenden (<code>clock_gettime()</code>, <code>std::chrono::system_clock</code>, <code>std::thread</code>, <code>pthread_create</code>, <code>/dev/urandom</code>, <code>rand()</code>). Zeit, Threading und Zufall müssen ausnahmslos über den <code>DeterministicClient</code> bezogen werden.</li>\n<li><strong>Run-to-Completion & Barrieren:</strong> Berechnungen innerhalb eines Aktivierungszyklus müssen vor dem nächsten <code>WaitForNextActivation()</code> vollständig terminieren.</li>\n<li><strong>Worker-Pool-Restriktionen:</strong> Parallelverarbeitung via <code>RunWorkerPool()</code> erfordert seiteneffektfreie Tasks, da das Framework die Reproduzierbarkeit der Abarbeitungsreihenfolge und Speicherzugriffe sicherstellt.</li>\n<li><strong>Koexistenz:</strong> Die Implementierung von <code>DeterministicClient</code> entbindet nicht von der Pflicht, die Standard-Zustandsmeldungen über den <code>ApplicationClient</code> abzusetzen, um Watchdog-Timeouts und Alive-Supervision-Fehler durch das Execution Management zu verhindern.</li>\n</ul>"}, {"id": "FIG-d96b0e2a2da5440d", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm (<code>cmp ArchitectureView-DeterministicClient</code>) zur Darstellung der Schnittstellenarchitektur auf System- und Prozessebene.</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die Interaktion zwischen einer deterministischen Adaptive Application und dem funktionalen Cluster <em>Execution Management</em> (<code>ara::exec</code>) der AUTOSAR Adaptive Platform (Release R18-03 / R1.4.0).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Abstraktion des Prozesslebenszyklus sowie die Entkopplung von nicht-deterministischen Plattform- und OS-Ressourcen (Systemuhr, Host-Threading, OS-Zufallsgeneratoren), um reproduzierbare Berechnungen (z. B. für automatisierte Fahrfunktionen, Replay-Simulationen und SIL/HIL-Validierung) zu garantieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Komponenten (UML Components)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Application</code>:</strong> POSIX-basierter Prozess der Adaptive Application, welcher Algorithmen mit deterministischer Ausführungscharakteristik kapselt. Fungiert als Client gegenüber beiden Schnittstellen.</li>\n<li><strong><code>Execution Management</code>:</strong> Zentraler Plattform-Daemon der Adaptive Platform (<code>ara::exec</code>), zuständig für Prozessüberwachung, deterministisches Scheduling und Lifecycle-Management. Stellt die korrespondierenden Ports bereit.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Klassen (Namespace <code>«ara::exec»</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>DeterministicClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Zugriffspunkt für deterministische Ausführungsmodelle.</li>\n<li>Methoden:</li>\n<li><code>+ GetActivationTime()</code>: Liefert den deterministischen Zeitstempel des aktuellen Ausführungszyklus (unabhängig von der realen Host-Laufzeit).</li>\n<li><code>+ GetNextActivationTime()</code>: Liefert den geplanten deterministischen Startzeitpunkt des Folgezyklus.</li>\n<li><code>+ GetRandom()</code>: Liefert pseudo-zufällige Werte aus einem reproduzierbaren, durch das Execution Management synchronisierten PRNG-Zustand.</li>\n<li><code>+ RunWorkerPool()</code>: Triggert die parallele Abarbeitung deterministischer Teilaufgaben über einen verwalteten Worker-Pool unter Vermeidung von Race Conditions.</li>\n<li><code>+ WaitForNextActivation()</code>: Blockierender Synchronisationspunkt, der den Prozess bis zur nächsten deterministischen Zyklus-Freigabe suspendiert.</li>\n<li><strong><code>ExecutionClient</code> (<code>«ara::exec»</code>):</strong></li>\n<li>Standard-Schnittstelle zur Lebenszyklus-Rückmeldung an das Execution Management.</li>\n<li>Methoden:</li>\n<li><code>+ ReportExecutionState()</code>: Meldet interne Prozesszustände (z. B. <code>kRunning</code>, <code>kTerminating</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Pfade</p>\n<ul class=\"fig-list\">\n<li><strong>Provided / Required Ports:</strong></li>\n<li><code>Application</code> nutzt (Required Interface / Socket) die Schnittstellen <code>DeterministicClient</code> und <code>ExecutionClient</code>.</li>\n<li><code>Execution Management</code> implementiert und exponiert (Provided Interface / Ball) beide Ports via IPC.</li>\n<li><strong>Kontrollpfad <code>Start / Terminate</code>:</strong></li>\n<li>Gerichtete Kontrollbeziehung (gestrichelte Linie) vom <code>Execution Management</code> zur <code>Application</code>. Signalisiert die Erzeugung (POSIX <code>fork</code>/<code>exec</code>) und Terminierung (<code>SIGTERM</code>/<code>SIGKILL</code>) des Prozesses.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Prozessinitialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> startet die <code>Application</code> (<code>Start</code>).</li>\n<li>Die Applikation initialisiert ihre Ressourcen und meldet über <code>ExecutionClient::ReportExecutionState(kRunning)</code> ihre Betriebsbereitschaft.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deterministische Regelschleife (Zyklische Abarbeitung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Applikation ruft blockierend <code>DeterministicClient::WaitForNextActivation()</code> auf.</li>\n<li>Nach Trigger durch das <code>Execution Management</code> erwacht die Applikation im definierten Ausführungszyklus (Aktivierungszeitpunkt).</li>\n<li>Abfrage von deterministischer Zeit (<code>GetActivationTime()</code>, <code>GetNextActivationTime()</code>) und deterministischer Pseudozufallszahlen (<code>GetRandom()</code>).</li>\n<li>Ggf. Abarbeitung paralleler Berechnungsaufgaben über <code>RunWorkerPool()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prozessterminierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Execution Management</code> signalisiert der <code>Application</code> das Beenden (<code>Terminate</code>).</li>\n<li>Die Applikation fährt kontrolliert herunter und meldet ihren Status über den <code>ExecutionClient</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Vorgaben:</strong></li>\n<li>Deterministische Anwendungen müssen für das Lifecycle-Management zwingend <code>ara::exec::ExecutionClient</code> nutzen und ihren Zustand via <code>ReportExecutionState()</code> melden.</li>\n<li>Für deterministisches Verhalten dürfen keine nicht-deterministischen OS-Dienste (wie Standard-Systemuhren, unkoordinierte POSIX-Threads oder systemweite Entropiequellen) genutzt werden; stattdessen ist strikt <code>ara::exec::DeterministicClient</code> zu verwenden.</li>\n<li>Das Execution Management steuert den Prozessstart und die Terminierung (<code>Start / Terminate</code>) normativ über Plattform-Mechanismen.</li>\n<li><strong>Entwickler-Hinweise:</strong></li>\n<li><code>WaitForNextActivation()</code> blockiert den aufrufenden Thread bis zur Freigabe des nächsten Ausführungszyklus durch das Execution Management.</li>\n<li>Bei Nutzung von <code>RunWorkerPool()</code> ist sicherzustellen, dass die Worker-Tasks frei von Daten-Races und unkontrollierten Synchronisationsprimitiven sind, um Replay-Fähigkeit zu gewährleisten.</li>\n</ul>"}], "trans": [{"from": "FIG-729fbdfbafa9bce4", "to": "FIG-d96b0e2a2da5440d", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Schnittstelle <code>ApplicationClient</code>:</strong> Ersetzt durch <code>ExecutionClient</code> (<code>«ara::exec»</code>).</li>\n<li><strong>Methode <code>+ ReportApplicationState()</code>:</strong> Ersetzt durch <code>+ ReportExecutionState()</code> in <code>ExecutionClient</code>.</li>\n<li><strong>Ports (Required/Provided):</strong> Port-Bezeichnungen zwischen <code>Application</code> und <code>Execution Management</code> von <code>ApplicationClient</code> auf <code>ExecutionClient</code> umbenannt.</li>\n</ul>"}]};
